"use client";

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import type { Product } from "@atelier/shared";
import { createProductSchema, updateProductSchema } from "@atelier/shared";
import { useAuth } from "@/contexts/AuthContext";

async function fetchProducts(shopId: string): Promise<Product[]> {
  const response = await fetch(`/api/products?shopId=${encodeURIComponent(shopId)}`);
  if (!response.ok) {
    throw new Error("Failed to fetch products");
  }
  return response.json();
}

async function fetchProduct(id: string): Promise<Product> {
  const response = await fetch(`/api/products/${id}`);
  if (!response.ok) {
    if (response.status === 404) {
      throw new Error("Product not found");
    }
    throw new Error("Failed to fetch product");
  }
  return response.json();
}

async function addProduct(
  product: Omit<Product, "id" | "createdAt" | "updatedAt">
): Promise<Product> {
  const response = await fetch("/api/products", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(product),
  });

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: "Failed to create product" }));
    const errorMessage = error.message 
      ? `${error.error || "Failed to create product"}: ${error.message}`
      : error.error || "Failed to create product";
    throw new Error(errorMessage);
  }

  return response.json();
}

async function updateProduct(
  id: string,
  updates: Partial<Omit<Product, "id" | "createdAt" | "updatedAt">>
): Promise<Product> {
  const response = await fetch(`/api/products/${id}`, {
    method: "PATCH",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(updates),
  });

  if (!response.ok) {
    if (response.status === 404) {
      throw new Error("Product not found");
    }
    const error = await response.json().catch(() => ({ error: "Failed to update product" }));
    throw new Error(error.error || "Failed to update product");
  }

  return response.json();
}

export function useProducts() {
  const { shopId } = useAuth();
  return useQuery({
    queryKey: ["products", shopId],
    queryFn: () => fetchProducts(shopId),
    enabled: !!shopId,
  });
}

export function useProduct(id: string) {
  return useQuery({
    queryKey: ["product", id],
    queryFn: () => fetchProduct(id),
    enabled: !!id,
  });
}

export function useAddProduct() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: addProduct,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["products"] });
    },
  });
}

export function useUpdateProduct() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, updates }: { id: string; updates: Parameters<typeof updateProduct>[1] }) =>
      updateProduct(id, updates),
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["products"] });
      queryClient.invalidateQueries({ queryKey: ["product", variables.id] });
    },
  });
}

async function deleteProduct(id: string): Promise<void> {
  const response = await fetch(`/api/products/${id}`, {
    method: "DELETE",
  });

  if (!response.ok) {
    if (response.status === 404) {
      throw new Error("Product not found");
    }
    const error = await response.json().catch(() => ({ error: "Failed to delete product" }));
    const errorMessage = error.message 
      ? `${error.error || "Failed to delete product"}: ${error.message}`
      : error.error || "Failed to delete product";
    throw new Error(errorMessage);
  }
}

export function useDeleteProduct() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: deleteProduct,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["products"] });
    },
  });
}
